package com.gameaggregator.buildservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="build_logs") public class BuildLog{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID buildId;@Column(nullable=false)public String level;@Lob @Column(nullable=false)public String message;@Column(nullable=false)public Instant createdAt=Instant.now();protected BuildLog(){}public BuildLog(UUID b,String l,String m){buildId=b;level=l;message=m;}}